mapper.select:
select id, order_no, org_id, amount, status, settle_time, remark, create_time, update_time
from settlement
where id = #{id}

select id, order_no, org_id, amount, status, settle_time, remark, create_time, update_time
from settlement
where order_no = #{orderNo}

select id, order_no, org_id, amount, status, settle_time, remark, create_time, update_time
from settlement
where org_id = #{orgId}
order by create_time desc
limit #{offset}, #{limit}

mapper.update:
update settlement
amount = #{amount}, status = #{status}, settle_time = #{settleTime}, remark = #{remark}, update_time = sysdate(),
where id = #{id}

mapper.select:
select id, order_no, org_id, amount, status, settle_time, remark, create_time, update_time
from settlement
